<section class="page-hero commerce-hero"><div><span class="eyebrow">PRIVATE / GUEST DESK</span><h1><?= e($title) ?></h1><p><?= t('A private pass keeps your purchases accessible without a site account.') ?></p></div><?= icon('lock') ?></section>
<?php if(!$owner): ?><section class="panel glass commerce-panel narrow"><?= form_start('guest_unlock','','',false) ?><?php field('token','Private guest pass','','password',['required'=>'required','maxlength'=>'64','minlength'=>'64','autocomplete'=>'off']);button('Unlock guest orders','','lock'); ?></form><p class="hint"><?= t('Email-only lookup is deliberately unavailable. Ask the merchant for manual assistance with your payment receipt if the pass is lost.') ?></p></section><?php else: ?>
<section class="panel glass commerce-panel"><details class="commerce-details"><summary><?= t('Reveal and save private guest pass') ?></summary><p class="hint"><?= t('Anyone with this pass can access these purchases. Keep it private; it is not sent automatically by email.') ?></p><code class="guest-pass"><?= e($_SESSION['guest_token']) ?></code><button type="button" class="btn secondary small" data-copy="<?= e($_SESSION['guest_token']) ?>"><?= t('Copy') ?></button></details><div class="row wrap"><?= form_start('guest_forget','','',false) ?><?php button('Lock this guest session','ghost small','lock'); ?></form><a class="btn secondary small" href="<?= e(url('login')) ?>"><?= t('Sign in') ?></a></div>
<?php if($me): ?><details class="commerce-details"><summary><?= t('Move these purchases to my account') ?></summary><?= form_start('guest_claim','','',false).hidden('token',$_SESSION['guest_token']) ?><?php check_field('confirm','Move all orders behind this pass to the currently signed-in account. This invalidates the pass.',false);button('Claim guest purchases','secondary','user'); ?></form></details><?php endif ?></section>
<div class="receipt-list"><?php foreach($sales as $sale): ?><a class="panel glass receipt-link" href="<?= e(url('receipt',['id'=>$sale['id']])) ?>"><span class="commerce-line-icon"><?= icon('box') ?></span><div class="grow"><strong>#<?= e($sale['sale_no']) ?></strong><p><?= dt((int)$sale['created_at'],'Y-m-d H:i') ?> &middot; <?= t($sale['status']) ?></p></div><strong><?= e($sale['currency'].' '.money((int)$sale['amount'])) ?></strong><?= icon('arrow') ?></a><?php endforeach ?></div><?php if(!$sales){empty_state('No guest orders yet.','box');} ?><?php endif ?>